350	+import {allHeadersRegex} from './regex';
351	+
352	+const tocStartMarkerRegex = /<!-- *toc *-->/i;
353	+const tocEndMarkerRegex = /<!-- *\/toc *-->/i;
354	+const tocRegion = /<!-- *toc *-->([\s\S]*?)<!-- *\/toc *-->/i;
355	+
356	+export type TocListStyle = 'bullet' | 'number';
357	+
358	+export type TocBulletMarker = '-' | '*' | '+';
359	+
360	+export type TocOrderedListStyle = 'always-one' | 'increment';
361	+
362	+export type TocOptions = {
363	+  listStyle: TocListStyle;
364	+  minLevel: number;
365	+  maxLevel: number;
366	+  title: string;
367	+  indentSize: number;
368	+  bulletMarker: TocBulletMarker;
369	+  orderedListStyle: TocOrderedListStyle;
370	+  useExplicitIds: boolean;
371	+  stripFormattingInToc: boolean;
372	+  excludeHeadings: string[];
373	+};
374	+
375	+type HeadingInfo = {
376	+  level: number;
377	+  text: string;
378	+};
379	+
380	+export function stripMarkdownFormatting(text: string): string {
381	+  let result = text.replace(/!\[\[[^\]]*\]\]/g, '');
382	+  result = result.replace(/!\[[^\]]*\]\([^)]*\)/g, '');
383	+  result = result.replace(/\[\[([^\]|]+)\|([^\]]+)\]\]/g, '$2');
384	+  result = result.replace(/\[\[([^\]]+)\]\]/g, '$1');
385	+  result = result.replace(/\[([^\]]*)\]\([^)]*\)/g, '$1');
386	+  result = result.replace(/\*\*([^*]*)\*\*/g, '$1');
387	+  result = result.replace(/__([^_]*)__/g, '$1');
388	+  result = result.replace(/~~([^~]*)~~/g, '$1');
389	+  result = result.replace(/==([^=]*)==/g, '$1');
390	+  result = result.replace(/\*([^*]*)\*/g, '$1');
391	+  result = result.replace(/(?<![a-zA-Z0-9])_([^_]*)_(?![a-zA-Z0-9])/g, '$1');
392	+  result = result.replace(/`([^`]*)`/g, '$1');
393	+  return result;
394	+}
395	+
396	+function parseExplicitHeadingId(rawHeadingText: string): {displayText: string; explicitId: string | null} {
397	+  const match = /^(.*?)(?:\s*\{#([A-Za-z0-9_-]+)\}\s*)$/.exec(rawHeadingText);
398	+  if (!match) {
399	+    return {displayText: rawHeadingText, explicitId: null};
400	+  }
401	+
402	+  return {
403	+    displayText: match[1].trimEnd(),
404	+    explicitId: match[2],
405	+  };
406	+}
407	+
408	+function normalizeExplicitHeadingId(explicitId: string): string {
409	+  let id = explicitId.trim().toLowerCase();
410	+  id = id.replace(/ /g, '-');
411	+  id = id.replace(/[^a-z0-9\-_]/g, '');
412	+  id = id.replace(/-{2,}/g, '-');
413	+  id = id.replace(/^-+|-+$/g, '');
414	+  return id;
415	+}
416	+
417	+function normalizeHeadingTextForComparison(text: string): string {
418	+  return stripMarkdownFormatting(text).trim().toLowerCase();
419	+}
420	+
421	+function buildHeadingExclusionPredicate(excludeHeadings: string[]): (headingText: string) => boolean {
422	+  const trimmed = (excludeHeadings ?? []).map((s) => (s ?? '').trim()).filter((s) => s !== '');
423	+  if (trimmed.length === 0) {
424	+    return () => false;
425	+  }
426	+
427	+  const literalMatches = new Set<string>();
428	+  const regexMatches: RegExp[] = [];
429	+
430	+  for (const entry of trimmed) {
431	+    if (entry.length >= 2 && entry.startsWith('/') && entry.endsWith('/')) {
432	+      const body = entry.slice(1, -1);
433	+      let compiledRegex: RegExp = null;
434	+      try {
435	+        compiledRegex = new RegExp(body, 'i');
436	+      } catch {
437	+        compiledRegex = null;
438	+      }
439	+
440	+      if (compiledRegex) {
441	+        regexMatches.push(compiledRegex);
442	+        continue;
443	+      }
444	+    }
445	+
446	+    literalMatches.add(normalizeHeadingTextForComparison(entry));
447	+  }
448	+
449	+  return (headingText: string) => {
450	+    const normalized = normalizeHeadingTextForComparison(headingText);
451	+    if (literalMatches.has(normalized)) {
452	+      return true;
453	+    }
454	+
455	+    for (const re of regexMatches) {
456	+      if (re.test(normalized)) {
457	+        return true;
458	+      }
459	+    }
460	+
461	+    return false;
462	+  };
463	+}
464	+
465	+export function generateAnchor(headingText: string): string {
466	+  let anchor = stripMarkdownFormatting(headingText);
467	+  anchor = anchor.replace(/#+\s*$/g, '');
468	+  anchor = anchor.trim().toLowerCase();
469	+  anchor = anchor.replace(/\s+/g, '-');
470	+  anchor = anchor.replace(/[^a-z0-9\-_]/g, '');
471	+  anchor = anchor.replace(/-{2,}/g, '-');
472	+  anchor = anchor.replace(/^-+|-+$/g, '');
473	+  return anchor;
474	+}
475	+
476	+export function deduplicateAnchor(baseAnchor: string, anchorCounts: Map<string, number>): string {
477	+  const count = anchorCounts.get(baseAnchor) ?? 0;
478	+  anchorCounts.set(baseAnchor, count + 1);
479	+
480	+  if (count === 0) {
481	+    return baseAnchor;
482	+  }
483	+
484	+  return `${baseAnchor}-${count}`;
485	+}
486	+
487	+export function extractHeadings(text: string, minLevel: number, maxLevel: number): HeadingInfo[] {
488	+  const tocMatch = tocRegion.exec(text);
489	+  let tocStart = -1;
490	+  let tocEnd = -1;
491	+  if (tocMatch) {
492	+    tocStart = tocMatch.index;
493	+    tocEnd = tocMatch.index + tocMatch[0].length;
494	+  }
495	+
496	+  const headings: HeadingInfo[] = [];
497	+  const headerRegex = new RegExp(allHeadersRegex.source, allHeadersRegex.flags);
498	+  let match: RegExpExecArray | null;
499	+
500	+  while ((match = headerRegex.exec(text)) !== null) {
501	+    const matchStart = match.index;
502	+
503	+    if (tocStart !== -1 && matchStart >= tocStart && matchStart < tocEnd) {
504	+      continue;
505	+    }
506	+
507	+    const level = match[2].length;
508	+
509	+    if (level >= minLevel && level <= maxLevel) {
510	+      headings.push({
511	+        level: level,
512	+        text: match[4],
513	+      });
514	+    }
515	+  }
516	+
517	+  return headings;
518	+}
