520	+export function generateTocContent(headings: HeadingInfo[], options: TocOptions): string {
521	+  if (headings.length === 0) {
522	+    return '';
523	+  }
524	+
525	+  const anchorCounts = new Map<string, number>();
526	+  const lines: string[] = [];
527	+
528	+  const indentSize = Math.max(0, options.indentSize);
529	+  const bulletMarker = options.bulletMarker;
530	+  const orderedListStyle = options.orderedListStyle;
531	+  let orderedIndex = 1;
532	+
533	+  const shouldExcludeHeading = buildHeadingExclusionPredicate(options.excludeHeadings);
534	+
535	+  if (options.title && options.title.trim() !== '') {
536	+    lines.push(options.title);
537	+    lines.push('');
538	+  }
539	+
540	+  for (const heading of headings) {
541	+    const indent = ' '.repeat((heading.level - options.minLevel) * indentSize);
542	+    const headingParts = options.useExplicitIds ? parseExplicitHeadingId(heading.text) : {displayText: heading.text, explicitId: null};
543	+    const rawDisplayText = headingParts.displayText;
544	+
545	+    if (shouldExcludeHeading(rawDisplayText)) {
546	+      continue;
547	+    }
548	+
549	+    const displayText = options.stripFormattingInToc ? stripMarkdownFormatting(rawDisplayText) : rawDisplayText;
550	+
551	+    const baseAnchor = headingParts.explicitId ? normalizeExplicitHeadingId(headingParts.explicitId) : generateAnchor(rawDisplayText);
552	+    const anchor = deduplicateAnchor(baseAnchor, anchorCounts);
553	+
554	+    if (options.listStyle === 'number') {
555	+      const marker = orderedListStyle === 'increment' ? `${orderedIndex}.` : '1.';
556	+      if (orderedListStyle === 'increment') {
557	+        orderedIndex += 1;
558	+      }
559	+      lines.push(`${indent}${marker} [${displayText}](#${anchor})`);
560	+      continue;
561	+    }
562	+
563	+    lines.push(`${indent}${bulletMarker} [${displayText}](#${anchor})`);
564	+  }
565	+
566	+  return lines.join('\n');
567	+}
568	+
569	+export function generateOrUpdateToc(text: string, options: TocOptions): string {
570	+  const startMatch = tocStartMarkerRegex.exec(text);
571	+
572	+  if (!startMatch) {
573	+    return text;
574	+  }
575	+
576	+  const headings = extractHeadings(text, options.minLevel, options.maxLevel);
577	+  const tocContent = generateTocContent(headings, options);
578	+
579	+  const afterStartIndex = startMatch.index + startMatch[0].length;
580	+  const endMatchAfterStart = tocEndMarkerRegex.exec(text.substring(afterStartIndex));
581	+
582	+  if (endMatchAfterStart) {
583	+    const endIndex = afterStartIndex + endMatchAfterStart.index;
584	+    const before = text.substring(0, startMatch.index + startMatch[0].length);
585	+    const after = text.substring(endIndex);
586	+
587	+    if (tocContent === '') {
588	+      return `${before}\n\n${after}`;
589	+    }
590	+
591	+    return `${before}\n\n${tocContent}\n\n${after}`;
592	+  }
593	+
594	+  const before = text.substring(0, startMatch.index + startMatch[0].length);
595	+  const after = text.substring(startMatch.index + startMatch[0].length);
596	+
597	+  if (tocContent === '') {
598	+    return `${before}\n\n<!-- /toc -->${after}`;
599	+  }
600	+
601	+  return `${before}\n\n${tocContent}\n\n<!-- /toc -->${after}`;
602	+}
