10	class HeaderIncrementOptions implements Options {
11	  startAtH2?: boolean = false;
12	}
13	
14	@RuleBuilder.register
15	export default class HeaderIncrement extends RuleBuilder<HeaderIncrementOptions> {
16	  constructor() {
17	    super({
18	      nameKey: 'rules.header-increment.name',
19	      descriptionKey: 'rules.header-increment.description',
20	      type: RuleType.HEADING,
21	      ruleIgnoreTypes: [IgnoreTypes.code, IgnoreTypes.math, IgnoreTypes.yaml, IgnoreTypes.link, IgnoreTypes.wikiLink, IgnoreTypes.tag],
22	    });
23	  }
24	  get OptionsClass(): new () => HeaderIncrementOptions {
25	    return HeaderIncrementOptions;
26	  }
27	  apply(text: string, options: HeaderIncrementOptions): string {
28	    let lastLevel = 0; // level of last header processed
29	    const minimumLevel = options.startAtH2 ? 2: 1;
30	    const headingLevelStartNumbers: Array<number> = [];
31	    // These are the heading level mappings for each heading level where the index + 1 is the heading level in the file
32	    // the value represents the new heading level to use with 0 meaning not mapped
33	    const headingLevels = [0, 0, 0, 0, 0, 0];
34	    const highestHeadingLevel = headingLevels.length;
35	
36	    return text.replace(allHeadersRegex, (_: string, $1: string = '', $2: string = '', $3: string = '', $4: string = '', $5: string = '') => {
37	      let level = $2.length;
38	      level = level <= highestHeadingLevel ? level : highestHeadingLevel;
39	
40	      if (headingLevels[level - 1] >= 0 && level < lastLevel) {
41	        let removeLevelTo = headingLevels.length;
42	        while (headingLevelStartNumbers.length !== 0 && level <= headingLevelStartNumbers[headingLevelStartNumbers.length - 1]) {
43	          removeLevelTo = headingLevelStartNumbers.pop();
44	        }
45	
46	        // in the rare case that a heading is lower than the first header in the file, make sure to reset all values for headers
47	        if (headingLevelStartNumbers.length === 0) {
48	          removeLevelTo = 0;
49	        } else {
50	          removeLevelTo--;
51	        }
52	
53	        for (let i = headingLevels.length - 1; i >= removeLevelTo; i--) {
54	          headingLevels[i] = 0;
55	        }
56	      }
57	
58	      if (headingLevels[level - 1] <= 0) {
59	        const startingLevelToFillIn = lastLevel;
60	        let newHeadingLevel = headingLevelStartNumbers.length + minimumLevel;
61	        newHeadingLevel = newHeadingLevel <= highestHeadingLevel ? newHeadingLevel : highestHeadingLevel;
62	
63	        for (let i = startingLevelToFillIn; i < level - 1; i++) {
64	          headingLevels[i] = newHeadingLevel - 1;
65	        }
66	
67	        headingLevelStartNumbers.push(level);
68	        headingLevels[level - 1] = newHeadingLevel;
69	      }
70	
71	      lastLevel = level;
72	
73	      return $1 + '#'.repeat(headingLevels[level - 1]) + $3 + $4 + $5;
74	    });
75	  }
76	  get exampleBuilders(): ExampleBuilder<HeaderIncrementOptions>[] {
77	    return [
78	      new ExampleBuilder({
79	        description: 'Heading levels are decremented as needed',
80	        before: dedent`
81	          # H1
82	          ### H3
83	          ### H3
84	          #### H4
85	          ###### H6
86	          ${''}
87	          We skipped a 2nd level heading
88	        `,
89	        after: dedent`
90	          # H1
91	          ## H3
92	          ## H3
93	          ### H4
94	          #### H6
95	          ${''}
96	          We skipped a 2nd level heading
97	        `,
98	      }),
