105	          We skip from 1 to 3
106	          ${''}
107	          ###### H6
108	          ${''}
109	          We skip from 3 to 6 leaving out 4, 5, and 6. Thus headings level 4 and 5 will be treated like H3 above until another H2 or H1 is encountered
110	          ${''}
111	          ##### H5
112	          ${''}
113	          We skipped 5 previously so it will be treated the same as the H3 above since it was the next lowest header that was to be decremented
114	          ${''}
115	          ## H2
116	          ${''}
117	          This resets the decrement section so the H6 below is decremented to an H3
118	          ${''}
119	          ###### H6
120	        `,
121	        after: dedent`
122	          # H1
123	          ## H3
124	          ${''}
125	          We skip from 1 to 3
126	          ${''}
127	          ### H6
128	          ${''}
129	          We skip from 3 to 6 leaving out 4, 5, and 6. Thus headings level 4 and 5 will be treated like H3 above until another H2 or H1 is encountered
130	          ${''}
131	          ## H5
132	          ${''}
133	          We skipped 5 previously so it will be treated the same as the H3 above since it was the next lowest header that was to be decremented
134	          ${''}
135	          # H2
136	          ${''}
137	          This resets the decrement section so the H6 below is decremented to an H3
138	          ${''}
139	          ## H6
140	        `,
141	      }),
142	      new ExampleBuilder({
143	        description: 'When `Start Header Increment at Heading Level 2 = true`, H1s become H2s and the other headers are incremented accordingly',
144	        before: dedent`
145	          # H1 becomes H2
146	          #### H4 becomes H3
147	          ###### H6
148	          ## H2
149	          ###### H6
150	          # H1
151	          ## H2
152	        `,
153	        after: dedent`
154	          ## H1 becomes H2
155	          ### H4 becomes H3
156	          #### H6
157	          ## H2
158	          ### H6
159	          ## H1
160	          ### H2
161	        `,
162	        options: {
163	          startAtH2: true,
164	        },
165	      }),
166	    ];
167	  }
